-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — tolerable misstatement definition
(1, 'Misstatements and Control Deficiencies', 'What is tolerable misstatement in the context of audit sampling?', '["The maximum amount of misstatement in the population that management is willing to accept", "The total amount of known misstatements discovered during audit testing", "The application of performance materiality to a particular sampling procedure", "The threshold below which all misstatements are considered clearly trivial"]'::jsonb, 2, 'Under AU-C 530.A3, tolerable misstatement is the application of performance materiality to a particular audit sampling procedure. It represents the maximum misstatement in the population that the auditor can accept and still conclude the sample results achieve the audit objective. It is not the same as the clearly trivial threshold (choice D), which is a much lower amount used to screen misstatements that need not be accumulated.', 'easy', 1),

-- Q2: hard / L4 — evaluate misstatement pattern indicating fraud
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Technologies, the engagement team discovers that three sales transactions totaling $180,000 were recorded on December 30, 2025, but the goods were not shipped until January 8, 2026. All three transactions involved the same regional sales manager and occurred in the final week of the fiscal year. The auditor should evaluate these misstatements by considering:', '["Only the quantitative impact of $180,000 against overall materiality to determine significance", "Whether the pattern and circumstances indicate a possible intentional misstatement requiring further investigation under AU-C 240", "Whether management has offered to reverse the entries, making further investigation unnecessary", "Only whether the revenue recognition policy was consistently applied across all quarters"]'::jsonb, 1, 'Under AU-C 240.35, when misstatements are identified, the auditor must consider whether they may be indicative of fraud. The pattern here—same manager, year-end timing, premature recognition—suggests possible intentional misstatement requiring fraud risk evaluation. Choice A is incorrect because qualitative factors, including fraud indicators, must also be assessed; purely quantitative analysis is insufficient under AU-C 450.11.', 'hard', 4),

-- Q3: medium / L3 — apply clearly trivial threshold concept
(1, 'Misstatements and Control Deficiencies', 'Atlas Consulting Group has established overall materiality at $500,000 and performance materiality at $375,000 for the current year audit. The engagement team sets the clearly trivial threshold at $25,000. During testing, the team identifies a $22,000 misstatement in prepaid expenses. Under AU-C 450, the auditor should:', '["Not accumulate the misstatement because it falls below the clearly trivial threshold", "Accumulate the misstatement and include it on the summary of uncorrected misstatements", "Report the misstatement to those charged with governance as a significant deficiency", "Require management to correct the misstatement before issuing the audit report"]'::jsonb, 0, 'Under AU-C 450.05, the auditor shall accumulate misstatements identified during the audit other than those that are clearly trivial. Since $22,000 is below the $25,000 clearly trivial threshold, the auditor is not required to accumulate it. Choice B is incorrect because AU-C 450 explicitly exempts clearly trivial amounts from the accumulation requirement, allowing the auditor to disregard them without further consideration.', 'medium', 3),

-- Q4: medium / L2 — management claims misstatement immaterial
(1, 'Misstatements and Control Deficiencies', 'During the audit of Birchwood Hospitality, the auditor identifies a $95,000 error in the depreciation calculation for hotel property. Management argues the misstatement is immaterial and declines to correct it. Overall materiality is $200,000. Under AU-C 450, the auditor''s most appropriate response is to:', '["Accept management''s assessment and issue an unmodified opinion without further action", "Immediately withdraw from the engagement due to management''s refusal", "Report the uncorrected misstatement only if additional misstatements are found later", "Include the misstatement on the summary of uncorrected misstatements, evaluate the aggregate effect, and communicate it to those charged with governance"]'::jsonb, 3, 'Under AU-C 450.12, the auditor must request management to correct all identified misstatements. When management refuses, the auditor should obtain an understanding of the reasons, accumulate the uncorrected misstatement, evaluate its aggregate effect, and communicate it to those charged with governance per AU-C 450.12–13. Choice A is incorrect because the auditor cannot simply accept management''s assertion without independently evaluating the aggregate impact.', 'medium', 2),

-- Q5: hard / L4 — multiple deficiencies across cycles = material weakness
(1, 'Misstatements and Control Deficiencies', 'While auditing Pinnacle Financial Group, the engagement team identifies three control deficiencies: (1) the accounts payable clerk can both create and approve vendors, (2) no independent review of journal entries over $50,000, and (3) the monthly bank reconciliation is prepared by the same person who processes cash receipts. Each deficiency alone is assessed as a significant deficiency. Under AU-C 265, the auditor should evaluate:', '["Each deficiency independently and communicate three separate significant deficiencies", "Only the deficiency with the largest potential dollar impact on the financial statements", "Whether the combination of deficiencies, considered together, constitutes a material weakness", "Whether management has compensating controls before classifying any of the deficiencies"]'::jsonb, 2, 'Under AU-C 265.A13, the auditor must consider whether individual control deficiencies that are not material weaknesses on their own may, in combination, represent a material weakness. Multiple significant deficiencies affecting different transaction cycles can collectively increase the reasonable possibility of a material misstatement. Choice A is incorrect because evaluating deficiencies only in isolation fails to meet AU-C 265''s requirement to assess their combined effect.', 'hard', 4),

-- Q6: medium / L2 — timing of deficiency communication
(1, 'Misstatements and Control Deficiencies', 'On March 15, 2026, during the audit of Westbrook Manufacturing for the year ended December 31, 2025, the engagement team identifies a material weakness in inventory controls. The audit report is expected to be issued on April 10, 2026. Under AU-C 265, the auditor should communicate this material weakness in writing:', '["Only after the audit report is issued to ensure all deficiencies are identified", "No later than 60 days after the report release date", "Within 30 days of identifying the weakness but before the next audit cycle", "Immediately upon discovery if it could affect interim financial reporting"]'::jsonb, 1, 'Under AU-C 265.13, the auditor shall communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. Choice D is incorrect because while timely communication is encouraged, AU-C 265 establishes the 60-day post-release deadline as the outer limit, not immediate notification upon discovery.', 'medium', 2),

-- Q7: easy / L1 — purpose of summary of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the purpose of maintaining a summary of uncorrected misstatements during an audit?', '["To evaluate whether uncorrected misstatements, individually or in aggregate, are material to the financial statements", "To provide management with a list of adjustments they are required to record", "To document the auditor''s calculation of performance materiality", "To identify which internal controls need to be tested during the current audit"]'::jsonb, 0, 'Under AU-C 450.06, the auditor accumulates uncorrected misstatements to evaluate whether they, individually or in aggregate, cause the financial statements to be materially misstated. This evaluation informs the auditor''s opinion. Choice B is incorrect because the summary is for the auditor''s evaluation—management is requested but not required to correct all items, and the auditor uses the summary to assess the overall impact on the audit opinion.', 'easy', 1),

-- Q8: medium / L3 — reassess performance materiality when misstatements accumulate
(1, 'Misstatements and Control Deficiencies', 'During the audit of Granite Ridge Logistics, the engagement team has identified $340,000 in aggregate uncorrected misstatements. Performance materiality was set at $400,000 and overall materiality at $600,000. As audit fieldwork continues, the auditor should:', '["Conclude that additional testing is unnecessary since the aggregate is below performance materiality", "Issue a qualified opinion because the misstatements exceed 50% of overall materiality", "Reduce the clearly trivial threshold to zero for all remaining audit procedures", "Reassess whether performance materiality remains appropriate given the level of detected misstatements and consider expanding procedures"]'::jsonb, 3, 'Under AU-C 450.07, when accumulated misstatements approach performance materiality, the auditor should consider whether there is more than a remote likelihood that additional uncorrected misstatements exist. At $340,000 of $400,000 performance materiality (85%), the auditor should reassess and potentially expand testing. Choice A is incorrect because proximity to performance materiality signals elevated risk of material misstatement and warrants additional professional judgment, not complacency.', 'medium', 3),

-- Q9: medium / L2 — management representation letter and uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'At the conclusion of the audit of Heritage Brands Inc., the auditor has accumulated a summary showing $75,000 in uncorrected misstatements that management has declined to adjust. Overall materiality is $300,000. Under AU-C 580, the management representation letter should include:', '["A statement that management believes the effects of uncorrected misstatements are immaterial, individually and in aggregate, to the financial statements as a whole", "A detailed listing of every audit adjustment proposed by the auditor during fieldwork", "An acknowledgment that the auditor''s opinion will be modified due to the uncorrected items", "A guarantee that no additional misstatements exist beyond those identified by the auditor"]'::jsonb, 0, 'Under AU-C 580.A8, management''s written representations should include a statement that management believes the effects of the uncorrected misstatements aggregated by the auditor are immaterial to the financial statements as a whole. The summary of uncorrected misstatements is typically attached. Choice D is incorrect because management cannot guarantee the absence of undetected misstatements; representations relate only to management''s belief about identified items.', 'medium', 2),

-- Q10: medium / L2 — prior period misstatement affecting current period
(1, 'Misstatements and Control Deficiencies', 'While auditing Cascade Electronics for the year ended December 31, 2025, the engagement team discovers that a $200,000 revenue overstatement from the 2024 audit was not corrected. The 2024 statements received an unmodified opinion. Under AU-C 450, the auditor should:', '["Ignore the prior period misstatement since the 2024 audit opinion has already been issued", "Automatically issue an adverse opinion on the 2025 financial statements", "Evaluate the effect of the uncorrected prior period misstatement on the current period financial statements", "Require management to restate the 2024 financial statements before continuing the 2025 audit"]'::jsonb, 2, 'Under AU-C 450.10, the auditor should consider the effect of uncorrected misstatements from prior periods on the current period''s financial statements. A prior-year revenue overstatement could affect current-year comparative amounts or opening balances. Choice A is incorrect because prior-period misstatements do not become irrelevant once an opinion is issued; their cumulative effect on current statements must still be evaluated.', 'medium', 2),

-- Q11: medium / L2 — IT general controls deficiency impact
(1, 'Misstatements and Control Deficiencies', 'During the audit of Summit Digital Media, the engagement team discovers that the company''s IT department has not applied critical security patches to its financial reporting system for over six months. Several application controls depend on this system operating correctly. Under AU-C 265, the auditor should classify this finding as:', '["An operational inefficiency that falls outside the scope of the financial statement audit", "At least a significant deficiency because the unpatched system affects the reliability of multiple application controls used in financial reporting", "A control deficiency only if a financial misstatement has actually resulted from the unpatched system", "An IT matter to be communicated to the IT department but not to those charged with governance"]'::jsonb, 1, 'Under AU-C 265.A7, when an IT general control weakness undermines the operating effectiveness of dependent application controls, it can affect multiple transaction cycles and financial statement assertions. An unpatched system supporting financial reporting represents at least a significant deficiency. Choice C is incorrect because deficiency severity is assessed based on the potential for misstatement, not just actual misstatements that have already occurred.', 'medium', 2),

-- Q12: easy / L1 — control deficiency definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what is the definition of a control deficiency?', '["A weakness that has resulted in a material misstatement of the financial statements", "A control that management has chosen not to implement due to cost-benefit considerations", "Any internal control that does not comply with regulatory requirements", "A condition where a control is designed, implemented, or operated in a way that does not allow management or employees to prevent or detect misstatements on a timely basis"]'::jsonb, 3, 'Under AU-C 265.07, a control deficiency exists when the design or operation of a control does not allow management or employees, in the normal course of performing their functions, to prevent or detect misstatements on a timely basis. Choice A is incorrect because a control deficiency does not require an actual misstatement to have occurred; the deficiency exists when the control''s design or operation is inadequate.', 'easy', 1),

-- Q13: medium / L2 — isolated deviation vs systemic deficiency
(1, 'Misstatements and Control Deficiencies', 'While auditing Riverstone Healthcare, the engagement team finds that the accounts payable department processed three invoices totaling $12,000 without proper purchase order matching during a period when the responsible clerk was on leave. Normal procedures were followed at all other times during the year. This finding most likely represents:', '["An isolated control deviation that does not necessarily indicate a design deficiency", "A material weakness in the purchasing cycle requiring immediate disclosure", "A significant deficiency because any failure in matching controls is inherently severe", "A fraud risk factor requiring expanded procedures across all transaction cycles"]'::jsonb, 0, 'Under AU-C 265.A8, the auditor considers the cause and frequency of deviations when evaluating severity. An isolated occurrence during a temporary staffing absence, with controls operating effectively at all other times, suggests a deviation rather than a systemic design flaw. Choice C is incorrect because severity depends on the likelihood and magnitude of potential misstatement, not a blanket rule that all matching failures are significant deficiencies.', 'medium', 2),

-- Q14: medium / L2 — documentation requirements for misstatements
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Golden Gate Financial, the engagement team has identified several misstatements, some corrected and some uncorrected by management. Under AU-C 450, the auditor''s workpapers should include documentation of:', '["Only the uncorrected misstatements that exceed overall materiality", "Only the misstatements that management declined to correct", "The amount below which misstatements are regarded as clearly trivial, all accumulated misstatements, and whether they have been corrected", "A complete listing of all transactions tested during the audit regardless of whether misstatements were found"]'::jsonb, 2, 'Under AU-C 450.14, the auditor should document the amount below which misstatements are considered clearly trivial, all misstatements accumulated during the audit and whether they have been corrected, and the auditor''s conclusion on whether uncorrected misstatements are material. Choice A is incorrect because documentation requirements apply to all accumulated misstatements, not only those exceeding materiality.', 'medium', 2),

-- Q15: easy / L1 — clearly trivial meaning
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what does it mean for a misstatement to be ''clearly trivial''?', '["The misstatement falls below overall materiality but above performance materiality", "The misstatement is of a size and nature that is inconsequential, whether taken individually or in aggregate", "The misstatement was caused by an error in estimation rather than a factual error", "The misstatement relates to disclosures rather than account balances"]'::jsonb, 1, 'Under AU-C 450.A2, clearly trivial misstatements are those of a size wholly inconsequential, whether taken individually or in aggregate, and whether judged by any criteria of size, nature, or circumstances. The threshold is set well below materiality. Choice A is incorrect because clearly trivial is a much lower threshold than materiality; items between performance materiality and overall materiality are not trivial and must be accumulated.', 'easy', 1),

-- Q16: medium / L3 — iron curtain vs rollover approach
(1, 'Misstatements and Control Deficiencies', 'During the audit of Northland Industries, the engagement team is evaluating $150,000 in uncorrected misstatements that originated in 2024 and affect the 2025 balance sheet. Performance materiality is $250,000. The auditor applies the rollover approach and the iron curtain approach to evaluate these misstatements. The key difference between these approaches is that the iron curtain approach:', '["Only considers misstatements that originated in the current year", "Evaluates the cumulative effect of misstatements on the income statement only", "Excludes misstatements that management has agreed to correct in subsequent periods", "Quantifies the misstatement based on the total accumulated amount in the balance sheet, regardless of when it originated"]'::jsonb, 3, 'Under SEC Staff Accounting Bulletin (SAB) 108, the iron curtain approach evaluates the cumulative effect of all prior-period uncorrected misstatements existing in the current balance sheet, regardless of when they originated. The rollover approach focuses only on the current-year effect. Choice A is incorrect because the iron curtain method specifically includes all periods'' accumulated misstatements, making it a broader measure than the rollover approach.', 'medium', 3),

-- Q17: easy / L1 — projected misstatement definition
(1, 'Misstatements and Control Deficiencies', 'What is a projected misstatement in the context of audit sampling?', '["The auditor''s best estimate of the total misstatement in the population extrapolated from misstatements found in the sample", "The exact dollar amount of errors identified during the audit sampling procedure", "A misstatement that management predicts will occur in future reporting periods", "The difference between the recorded amount and the auditor''s expected value based on analytical procedures"]'::jsonb, 0, 'Under AU-C 530.A21, a projected misstatement is the auditor''s best estimate of the misstatement in the entire population, derived by extrapolating the misstatements found in the sample to the population. This projection is then accumulated with other misstatements. Choice B is incorrect because it describes known misstatements found in the sample itself, not the extrapolated estimate of total population misstatement.', 'easy', 1),

-- Q18: hard / L4 — uncorrected misstatements impact on audit opinion
(1, 'Misstatements and Control Deficiencies', 'During the audit of Crestfield Manufacturing, the engagement team has accumulated uncorrected misstatements totaling $480,000 that overstate net income. Overall materiality is $500,000, and performance materiality is $375,000. Management refuses to make corrections. The misstatements span inventory valuation, depreciation, and accrued liabilities across multiple financial statement line items. The auditor should:', '["Issue an unmodified opinion because the aggregate does not exceed overall materiality", "Issue a disclaimer of opinion due to the scope limitation created by management''s refusal", "Consider the qualitative characteristics and pervasiveness of the misstatements and likely issue a qualified or adverse opinion even though the aggregate is just below materiality", "Request an extension of fieldwork to identify additional misstatements that would bring the total above materiality"]'::jsonb, 2, 'Under AU-C 450.11, the auditor evaluates both quantitative and qualitative factors, including whether the misstatements affect trends, compliance with covenants, or user decisions. At 96% of materiality across multiple line items with a consistent overstatement direction, the pervasive nature and qualitative significance likely warrant opinion modification. Choice A is incorrect because a purely mechanical comparison to materiality ignores the qualitative assessment required by AU-C 450.', 'hard', 4),

-- Q19: easy / L1 — accumulation threshold for misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, the auditor is required to accumulate misstatements identified during the audit unless they are:', '["Related to estimates rather than factual errors", "Clearly trivial", "Below performance materiality", "Voluntarily corrected by management"]'::jsonb, 1, 'Under AU-C 450.05, the auditor shall accumulate misstatements identified during the audit other than those that are clearly trivial. The clearly trivial threshold is set well below materiality as an amount beneath which misstatements need not be accumulated. Choice C is incorrect because the threshold for accumulation is clearly trivial, not performance materiality; many misstatements below performance materiality still must be accumulated and evaluated.', 'easy', 1),

-- Q20: medium / L2 — repeat communication of unremediated deficiency
(1, 'Misstatements and Control Deficiencies', 'During the current year audit of Lakeview Pharmaceuticals, the engagement team identifies the same material weakness in inventory controls that was communicated in the prior year. Management acknowledged the weakness but has not yet implemented corrective action. Under AU-C 265, the auditor should:', '["Not communicate the weakness again since it was already reported in the prior year", "Downgrade the finding to a significant deficiency since management is aware of it", "Report the weakness only in the management letter, not to those charged with governance", "Communicate the material weakness again in writing, noting that it was previously communicated"]'::jsonb, 3, 'Under AU-C 265.A19, significant deficiencies and material weaknesses that remain unremediated must be communicated in writing each year they continue to exist. The auditor may reference the prior communication and note that corrective action has not been taken. Choice A is incorrect because the communication requirement applies each audit period regardless of whether the deficiency was previously reported.', 'medium', 2),

-- Q21: medium / L3 — qualitative factors in misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'While auditing Pacific Coast Distributors, the engagement team identifies a $30,000 uncorrected misstatement that overstates revenue. Overall materiality is $800,000. However, the misstatement causes the company to barely meet a debt covenant requiring a minimum current ratio of 1.5:1. Under AU-C 450, the most important consideration for the auditor is:', '["The qualitative significance of the misstatement, including its effect on debt covenant compliance, which may make it material despite its small dollar amount", "That the misstatement is clearly immaterial because $30,000 is only 3.75% of overall materiality", "Whether the misstatement was caused by fraud or error, as only fraudulent misstatements require qualitative evaluation", "Whether management has provided a written representation that the covenant is not at risk of violation"]'::jsonb, 0, 'Under AU-C 450.11, the auditor considers the effect of uncorrected misstatements related to specific accounts and qualitative factors such as the effect on compliance with debt covenants. A quantitatively small misstatement can be qualitatively material if it changes covenant compliance outcomes. Choice B is incorrect because AU-C 450 explicitly requires qualitative evaluation beyond mechanical quantitative thresholds when circumstances give the misstatement heightened significance.', 'medium', 3),

-- Q22: easy / L2 — factual misstatement classification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redwood Technology Solutions, the engagement team identifies an error in the inventory valuation calculation where the cost formula was incorrectly applied to 200 items. The error was verified by re-performing the calculation. This misstatement is best classified as:', '["A projected misstatement because it was found during inventory testing", "A judgmental misstatement because it involves a valuation method", "A factual misstatement because the error is specifically identified and verified", "A likely misstatement because the inventory population may contain additional errors"]'::jsonb, 2, 'Under AU-C 450.A4, a factual misstatement is one about which there is no doubt, typically identified through specific testing and verification. A verified calculation error in inventory is a factual misstatement. Choice B is incorrect because judgmental misstatements arise from differences in management''s estimates or judgments that the auditor considers unreasonable; a calculation error involves no judgment.', 'easy', 2),

-- Q23: hard / L4 — compensating controls and deficiency gap analysis
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sterling Electronics, the engagement team identifies that the controller has both authorization and recording responsibilities for all journal entries, a clear segregation of duties deficiency. However, the CFO reviews a monthly summary report of all journal entries over $10,000, and an external accounting firm performs quarterly reviews. Annual transactions total $50 million, with approximately 2,000 journal entries under $10,000 totaling $8 million. The auditor should conclude that:', '["The compensating controls fully mitigate the deficiency, so no communication is needed", "The compensating controls partially mitigate the risk but the deficiency remains at least a significant deficiency because entries under $10,000 are not subject to independent review", "The deficiency is automatically a material weakness whenever segregation of duties is absent", "The quarterly external reviews eliminate the need to classify the deficiency at any level"]'::jsonb, 1, 'Under AU-C 265.A12, the auditor evaluates compensating controls when assessing severity. While the CFO review and external quarterly reviews mitigate risk for larger entries, entries under $10,000 ($8 million annually) lack independent review, leaving a gap in the compensating control structure. Choice C is incorrect because deficiency classification requires analysis of magnitude and likelihood, not automatic categorization based solely on the type of control failure.', 'hard', 4),

-- Q24: hard / L4 — netting misstatements across line items
(1, 'Misstatements and Control Deficiencies', 'The audit of Ironbridge Construction reveals the following uncorrected misstatements: inventory overstated by $120,000, revenue understated by $45,000, and depreciation overstated by $80,000. Overall materiality is $300,000 and performance materiality is $225,000. Management refuses corrections. All misstatements affect different financial statement line items. The auditor should:', '["Evaluate the net effect but also consider the gross effect on individual line items, because netting misstatements across different line items is generally inappropriate", "Simply net the misstatements and issue an unmodified opinion since the net amount is below materiality", "Issue an adverse opinion because three separate misstatements demonstrate pervasive weaknesses", "Require management to correct only the $120,000 inventory overstatement since it is the largest individual item"]'::jsonb, 0, 'Under AU-C 450.11, when evaluating aggregate misstatements, the auditor should not simply offset misstatements affecting different line items. While the net effect on income may appear below materiality, each line item''s misstatement may be material relative to that specific balance or disclosure. Choice B is incorrect because netting misstatements across different line items obscures the impact on individual financial statement elements that users analyze separately.', 'hard', 4),

-- Q25: hard / L3 — prior year reversal effect on current year income
(1, 'Misstatements and Control Deficiencies', 'During the audit of Clearwater Energy for the year ended December 31, 2025, the auditor discovers that a prior-year accrued liability understatement of $275,000 was not corrected. The error originated in 2024 and reversed naturally into 2025 income. Overall materiality is $400,000 for both years. The auditor should evaluate the effect on 2025 by recognizing that:', '["The misstatement no longer exists because it naturally reversed and requires no further consideration", "The 2024 opinion must be withdrawn before the 2025 audit can be completed", "The misstatement only affects the balance sheet and has no income statement implications in either year", "The reversal overstates 2025 income by approximately $275,000, and this current-year effect must be included in the evaluation of uncorrected misstatements"]'::jsonb, 3, 'Under AU-C 450.10, the auditor evaluates the effect of prior-period uncorrected misstatements on current-period financial statements. A prior-year expense understatement that reverses naturally inflates current-year income by the same amount, creating a turnaround effect. Choice A is incorrect because while the balance sheet error may reverse, the income statement effect shifts between periods, requiring evaluation of the current-year impact.', 'hard', 3),

-- Q26: medium / L3 — design vs operating effectiveness deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Summit Financial Services, the engagement team examines a control requiring dual authorization for wire transfers exceeding $25,000. The control is formally documented in the company''s procedures manual and properly designed to prevent unauthorized transfers. However, testing reveals that in 15 of 40 sampled transactions, only one person authorized the transfer. The auditor should classify this as:', '["A design deficiency because the control''s threshold amount is set too high", "An operating effectiveness deficiency because the control is properly designed but not consistently executed", "Acceptable performance because fewer than half of the sampled items had deviations", "A monitoring deficiency unrelated to the control over wire transfers"]'::jsonb, 1, 'Under AU-C 265.A6, a deficiency in operation exists when a properly designed control does not operate as designed or when the person performing the control lacks the necessary authority or competence. The dual-authorization control is well designed but fails in execution 37.5% of the time. Choice C is incorrect because a 37.5% deviation rate is not acceptable; it indicates the control is not reliably preventing unauthorized transfers as intended.', 'medium', 3),

-- Q27: easy / L1 — communication form for deficiencies below significant
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, how should control deficiencies that are less severe than significant deficiencies be communicated?', '["In writing to those charged with governance within 60 days of the report release date", "They must be communicated to the SEC through the annual report filing", "The form of communication is at the auditor''s discretion and may be oral or written", "They need not be communicated to anyone and should only be documented in the workpapers"]'::jsonb, 2, 'Under AU-C 265.14, the auditor should communicate to management control deficiencies identified during the audit that are of sufficient importance to merit management''s attention. The standard does not mandate written communication for deficiencies below significant deficiency level, leaving the form to the auditor''s judgment. Choice D is incorrect because even non-significant deficiencies that merit management''s attention should be communicated, though written form is not required.', 'easy', 1),

-- Q28: medium / L3 — severity classification analytical steps
(1, 'Misstatements and Control Deficiencies', 'While auditing Bayside Electronics, the engagement team identifies a control deficiency in the payroll processing cycle. To determine whether this deficiency represents a significant deficiency or material weakness, the auditor''s primary analytical steps should be to:', '["Assess the magnitude of the potential misstatement that could result and the likelihood that the control would fail to prevent or detect it", "Determine whether the deficiency has been communicated to management in a prior year audit", "Calculate the actual dollar impact of misstatements that have occurred during the current year", "Evaluate whether the company''s external auditor in the prior year identified the same deficiency"]'::jsonb, 0, 'Under AU-C 265.A11, severity assessment requires evaluating both the magnitude of the potential misstatement (what could go wrong) and the likelihood that the existing controls would fail to prevent or detect a misstatement. This two-dimensional assessment determines classification. Choice C is incorrect because severity is based on the potential for misstatement, not only actual misstatements that have occurred; a deficiency can be a material weakness even without any current-year errors.', 'medium', 3),

-- Q29: medium / L3 — component auditor misstatements in group audit
(1, 'Misstatements and Control Deficiencies', 'During a group audit of Apex Global Holdings, the group engagement team receives a summary from a component auditor indicating $90,000 in uncorrected misstatements at a significant subsidiary. Group materiality is $500,000, and component materiality was set at $150,000. Under AU-C 600, the group engagement team should:', '["Disregard the component misstatements if they are below group materiality", "Request the component auditor to reperform all testing procedures until no misstatements remain", "Evaluate the component misstatements only in the context of the component''s own financial statements", "Include the component''s uncorrected misstatements in the group''s aggregate summary and evaluate their effect at the group level"]'::jsonb, 3, 'Under AU-C 600.A60, the group engagement team must consider misstatements identified by component auditors when evaluating uncorrected misstatements at the group level. Component misstatements that are immaterial individually may become material when aggregated with misstatements from other components. Choice A is incorrect because even misstatements below group materiality must be accumulated; their combined effect with other component and group-level misstatements may be material.', 'medium', 3),

-- Q30: easy / L1 — deadline for written communication
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what is the deadline for written communication of significant deficiencies and material weaknesses to those charged with governance?', '["Within 30 days of completing audit fieldwork", "No later than 60 days following the report release date", "Before the financial statements are filed with the SEC", "At the next scheduled meeting of the audit committee"]'::jsonb, 1, 'Under AU-C 265.13, the auditor shall communicate significant deficiencies and material weaknesses identified during the audit in writing to those charged with governance no later than 60 days following the report release date. This allows sufficient time for the auditor to complete the evaluation. Choice A is incorrect because the deadline is tied to the report release date, not the completion of fieldwork, giving the auditor additional time to properly classify deficiencies.', 'easy', 1)
;

COMMIT;
